/** Independently required owners and the actual canonical ordered SQL journal
 * cannot be omitted by coherently recomputing a binding fingerprint. */
export function assertEmployeeLifecycleSourceClosure(sources,journal){
 assert(Array.isArray(sources)&&new Set(sources).size===sources.length);
 for(const file of sources)assert(typeof file==='string'&&!file.startsWith('/')&&!file.includes('\\')&&!file.includes('\0')&&file.split('/').every(part=>part!==''&&part!=='.'&&part!=='..'));
 for(const file of EMPLOYEE_LIFECYCLE_CRITICAL)assert(sources.includes(file),'Employee critical source omitted: '+file);
 if(journal!==undefined){
  assert(Array.isArray(journal.entries)&&journal.entries.length>0);const tags=new Set();
  for(const row of journal.entries){assert(typeof row.tag==='string'&&/^[A-Za-z0-9_-]{1,180}$/.test(row.tag)&&!tags.has(row.tag));tags.add(row.tag);assert(sources.includes('db/migrations/'+row.tag+'.sql'),'Canonical employee migration source omitted');}
 }
 return sources;
}
